package cn.zhuatech.privacy.deep;import cn.zhuatech.privacy.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.time.*;@RestController @RequestMapping("/api/privacy-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/activities")ApiResponse<?> activity(@Valid @RequestBody DeepDomainService.ActivityRequest r){return ApiResponse.ok(s.createActivity(r));}@PostMapping("/activities/{id}/assessments")ApiResponse<?> assessment(@PathVariable Long id,@Valid @RequestBody DeepDomainService.AssessmentRequest r){return ApiResponse.ok(s.assess(id,r));}@PostMapping("/activities/{id}/submit")ApiResponse<?> submit(@PathVariable Long id){return ApiResponse.ok(s.submit(id));}@PostMapping("/consents")ApiResponse<?> consent(@Valid @RequestBody DeepDomainService.ConsentRequest r){return ApiResponse.ok(s.grantConsent(r));}@PostMapping("/consents/{id}/revoke")ApiResponse<?> revoke(@PathVariable Long id){return ApiResponse.ok(s.revokeConsent(id));}@PostMapping("/requests")ApiResponse<?> request(@Valid @RequestBody DeepDomainService.SubjectRequestInput r){return ApiResponse.ok(s.createRequest(r));}@PostMapping("/requests/{id}/verify")ApiResponse<?> verify(@PathVariable Long id,@Valid @RequestBody DeepDomainService.VerifyRequest r){return ApiResponse.ok(s.verify(id,r));}@PostMapping("/requests/{id}/fulfill")ApiResponse<?> fulfill(@PathVariable Long id,@Valid @RequestBody DeepDomainService.FulfillRequest r){return ApiResponse.ok(s.fulfill(id,r));}}
